function isPassing(score) {
  return score >= 70;
}

function passingLabels(scores) {
  return scores.filter(isPassing).map((score) => `Score ${score}`);
}

const clean = text => text.trim();
const lower = text => text.toLowerCase();
const key = text => lower(clean(text));
key('  Blue '); // 'blue'
